CREATE DATABASE IF NOT EXISTS ajira_v4 CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ajira_v4;
CREATE TABLE IF NOT EXISTS members(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(150) NOT NULL,reg_number VARCHAR(60) NOT NULL,phone VARCHAR(20) NOT NULL,email VARCHAR(150) NOT NULL,password_hash VARCHAR(255) DEFAULT NULL,profile_image VARCHAR(255) DEFAULT NULL,bio VARCHAR(500) DEFAULT NULL,course_year VARCHAR(120) NOT NULL,member_type ENUM('new','renewal') DEFAULT 'new',is_active TINYINT(1) DEFAULT 0,payment_method ENUM('till','paybill','other') DEFAULT 'till',payment_ref VARCHAR(80) DEFAULT NULL,payment_status ENUM('not_submitted','submitted','verified','rejected') NOT NULL DEFAULT 'not_submitted',payment_proof VARCHAR(255) DEFAULT NULL,payment_amount DECIMAL(10,2) DEFAULT NULL,payment_submitted_at DATETIME DEFAULT NULL,reviewed_at DATETIME DEFAULT NULL,registered_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,activated_at TIMESTAMP NULL DEFAULT NULL,expires_at DATETIME DEFAULT NULL,deactivated_at DATETIME DEFAULT NULL,deactivation_reason VARCHAR(255) DEFAULT NULL,UNIQUE KEY uq_reg(reg_number),INDEX idx_active(is_active),INDEX idx_expiry(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS member_notifications(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,member_id INT UNSIGNED NOT NULL,title VARCHAR(160) NOT NULL,message TEXT NOT NULL,is_read TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_member_notifications(member_id,is_read,created_at),CONSTRAINT fk_member_notifications_member FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS events(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(220) NOT NULL,description TEXT DEFAULT NULL,event_date DATETIME NOT NULL,location VARCHAR(220) DEFAULT NULL,is_online TINYINT(1) DEFAULT 0,is_published TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS contact_messages(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(150) NOT NULL,subject VARCHAR(200) DEFAULT NULL,message TEXT NOT NULL,is_read TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS admin_users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(80) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,last_login TIMESTAMP NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS notifications(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(160) NOT NULL,message TEXT NOT NULL,audience ENUM('public','members') NOT NULL DEFAULT 'public',link VARCHAR(500) DEFAULT NULL,expires_at DATETIME DEFAULT NULL,created_by INT UNSIGNED DEFAULT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_notifications_audience(audience,created_at,expires_at),CONSTRAINT fk_notifications_admin FOREIGN KEY(created_by) REFERENCES admin_users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS notification_reads(notification_id INT UNSIGNED NOT NULL,member_id INT UNSIGNED NOT NULL,read_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(notification_id,member_id),CONSTRAINT fk_notification_reads_notification FOREIGN KEY(notification_id) REFERENCES notifications(id) ON DELETE CASCADE,CONSTRAINT fk_notification_reads_member FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
